#include <zephyr/kernel.h>
#include <zephyr/pm/pm.h>
#include <zephyr/pm/policy.h>
#include <zephyr/ztest.h>

#define DUMMY_LATENCY 10000

static const struct pm_state_info *get_state_info(enum pm_state state)
{
	const struct pm_state_info *info;

	for (int i = 0; (info = pm_state_get(i, NULL)) != NULL; i++) {
		if (info->state == state) {
			return info;
		}
	}

	return NULL;
}

static void test_pm_policy_next_state_default(void)
{
	const struct pm_state_info *info;

	info = pm_policy_next_state(0, NULL, NULL);
	zassert_not_null(info, "pm_policy_next_state returned NULL");
}

static void test_pm_policy_next_state_default_allowed(void)
{
	int min_residency, min_latency;
	const struct pm_state_info *info;

	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_not_null(info, "pm_policy_next_state returned NULL");
	zassert_true(info->exit_latency_us <= min_latency, "invalid latency");
	zassert_true(info->min_residency_us <= min_residency, "invalid residency");
}

static void test_pm_policy_next_state_default_latency(void)
{
	int min_residency, min_latency;
	const struct pm_state_info *info;

	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_not_null(info, "pm_policy_next_state returned NULL");

	min_latency = info->exit_latency_us - 1;
	TC_PRINT("Latency changed to %d\n", min_latency);
	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_is_null(info, "pm_policy_next_state returned not NULL");

	min_latency = info->exit_latency_us;
	TC_PRINT("Latency changed to %d\n", min_latency);
	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_not_null(info, "pm_policy_next_state returned NULL");

	min_latency = 50000;
	TC_PRINT("Latency changed to %d\n", min_latency);
	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_not_null(info, "pm_policy_next_state returned NULL");

	min_latency = -1;
	TC_PRINT("Latency changed to %d\n", min_latency);
	info = pm_policy_next_state(0, &min_residency, &min_latency);
	zassert_not_null(info, "pm_policy_next_state returned NULL");
}

static void test_pm_policy_state_all_lock(void)
{
	const struct pm_state_info *info;

	/* lock all states */
	for (int i = 0; (info = pm_state_get(i, NULL)) != NULL; i++) {
		if (info->state > PM_STATE_RUNTIME_IDLE) {
			pm_policy_state_lock_get(info->state, PM_ALL_SUBSTATES);
		}
	}

	/* check that no states are available */
	info = pm_policy_next_state(0, NULL, NULL);
	zassert_equal(info->state, PM_STATE_RUNTIME_IDLE, "wrong state");

	/* unlock all states */
	for (int i = 0; (info = pm_state_get(i, NULL)) != NULL; i++) {
		if (info->state > PM_STATE_RUNTIME_IDLE) {
			pm_policy_state_lock_put(info->state, PM_ALL_SUBSTATES);
		}
	}

	/* check that states are available again */
	info = pm_policy_next_state(0, NULL, NULL);
	zassert_true(info->state > PM_STATE_RUNTIME_IDLE, "wrong state");
}

struct pm_policy_state_constraints_test_data {
	enum pm_state state;
	uint8_t substate_id;
};

static const struct pm_policy_state_constraints_test_data constraints[] = {
	{
		.state = PM_STATE_SUSPEND_TO_RAM,
		.substate_id = 10,
	},
	{
		.state = PM_STATE_SUSPEND_TO_RAM,
		.substate_id = 100,
	},
};

static void test_pm_policy_state_constraints(void)
{
	const struct pm_state_info *info;
	bool found_runtime_idle;

	/*
	 * Check that runtime idle is enabled in this build. pm_state_get()
	 * iterates over all enabled states, ignoring any locks.
	 */
	found_runtime_idle = (get_state_info(PM_STATE_RUNTIME_IDLE) != NULL);
	zassert_true(found_runtime_idle, "PM_STATE_RUNTIME_IDLE is not enabled");

	/*
	 * Set some constraints on a different state and check that runtime
	 * idle is still present in the list of enabled states.
	 */
	for (int i = 0; i < ARRAY_SIZE(constraints); i++) {
		TC_PRINT("Constraint %d: state=%d, substate_id=%d\n", i, constraints[i].state,
			 constraints[i].substate_id);
		pm_policy_state_lock_get(constraints[i].state, constraints[i].substate_id);
	}

	found_runtime_idle = (get_state_info(PM_STATE_RUNTIME_IDLE) != NULL);
	zassert_true(found_runtime_idle, "PM_STATE_RUNTIME_IDLE disappeared from enabled list");

	/*
	 * Release constraints and check again.
	 */
	for (int i = 0; i < ARRAY_SIZE(constraints); i++) {
		pm_policy_state_lock_put(constraints[i].state, constraints[i].substate_id);
	}

	found_runtime_idle = (get_state_info(PM_STATE_RUNTIME_IDLE) != NULL);
	zassert_true(found_runtime_idle, "PM_STATE_RUNTIME_IDLE disappeared from enabled list");

	/*
	 * Lock runtime idle and check that it is not selected by the policy
	 * manager.
	 */
	pm_policy_state_lock_get(PM_STATE_RUNTIME_IDLE, PM_ALL_SUBSTATES);

	info = pm_policy_next_state(0, NULL, NULL);
	zassert_true(info == NULL || info->state != PM_STATE_RUNTIME_IDLE,
		     "runtime idle selected when locked");

	/*
	 * Unlock runtime idle and check that it can be selected again.
	 */
	pm_policy_state_lock_put(PM_STATE_RUNTIME_IDLE, PM_ALL_SUBSTATES);

	info = pm_policy_next_state(0, NULL, NULL);
	/* Assuming RUNTIME_IDLE is the best choice for a tickless idle of 0 ticks */
	zassert_not_null(info, "no state selected when unlocked");
	zassert_equal(info->state, PM_STATE_RUNTIME_IDLE,
		      "runtime idle not selected when unlocked");
}

void test_main(void)
{
	ztest_test_suite(pm_policy_api, ztest_unit_test(test_pm_policy_next_state_default),
			 ztest_unit_test(test_pm_policy_next_state_default_allowed),
			 ztest_unit_test(test_pm_policy_next_state_default_latency),
			 ztest_unit_test(test_pm_policy_state_all_lock),
			 ztest_unit_test(test_pm_policy_state_constraints));
	ztest_run_test_suite(pm_policy_api);
}
